set-variable.value:
#[%dw 2.0
output text/plain
var operation = vars.variablesRequest.operation
---
write({
	"Audit": {
		"Canal": vars.headers.name
	} filterObject ((value, key) -> value != null),
	"Agenda": {
		"Address_Comments": payload.schedule.addressComment,
		"Booking": payload.schedule.booking,
		"Date": payload.schedule.date,
		"Timeslot": payload.schedule.timeSlot
	} filterObject ((value, key) -> value != null),
	"Contact": {
		"Email": payload.contact.email,
		"First_Name": payload.contact.firstName,
		"Phone": payload.contact.phone
	} filterObject ((value, key) -> value != null),
	"Customer": {
		"Comunicaciones_Canales": payload.customer.communicationChannels,
		"Comunicaciones_Horarios": payload.customer.communicationDays,
		"Comunicaciones_Update": payload.customer.communicationUpdate,
		"Email": payload.customer.email,
		"First_Name": payload.customer.firstName,
		"Phone": payload.customer.phone
	} filterObject ((value, key) -> value != null),
	"Order_Number": payload.order.orderNum,
	"Plan": {
		"Accept_Clause": payload.order.fttx.acceptClause,
		"Accept_Contract": payload.order.fttx.acceptContract,
		"Plan": payload.order.fttx.plan,
		"SVAs": payload.order.fttx.svas
	} filterObject ((value, key) -> value != null)
} filterObject ((value, key) -> value != null),
"application/json"
)]

#[%dw 2.0
output text/plain
var operation = vars.variablesRequest.operation
---
write({
	"Audit": {
		"Canal": vars.headers.name
	} filterObject ((value, key) -> value != null),
	"Document_Number": payload.customer.documentNumber,
	"Document_Type": payload.customer.documentType,
	"Phone": payload.customer.phone,
	"Surname": payload.customer.surname
} filterObject ((value, key) -> value != null),
"application/json"
)]

#[%dw 2.0
output text/plain
var operation = vars.variablesRequest.operation
---
write({
	"Audit": {
		"Canal": vars.headers.name
	} filterObject ((value, key) -> value != null),
	"Code": payload.order.otpCode,
	"Num_Order": payload.order.orderNum,
	"Type": payload.order.otpType
} filterObject ((value, key) -> value != null),
"application/json"
)]

#[%dw 2.0
output text/plain
var operation = vars.variablesRequest.operation
---
write({
	"Audit": {
		"Canal": vars.headers.name
	} filterObject ((value, key) -> value != null),
	"Answers": map(payload.customer.answers, ((answer) -> {
		"Answer": answer.answer,
		"Question": answer.question
	} filterObject ((value, key) -> value != null))),
	"Id": payload.order.questionnaireId,
	"Num_Order": payload.order.orderNum
} filterObject ((value, key) -> value != null),
"application/json"
)]

